import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Coding Harness","description":"","frontmatter":{},"headers":[],"relativePath":"design/coding-harness.md","filePath":"design/coding-harness.md","lastUpdated":1795180391000}'),o={name:"design/coding-harness.md"};function n(r,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="coding-harness" tabindex="-1">Coding Harness <a class="header-anchor" href="#coding-harness" aria-label="Permalink to &quot;Coding Harness&quot;">​</a></h1><p>Hearth&#39;s native executor is a general-purpose agent runtime. This document describes the coding profile added on top of it and the gap it closes against <a href="https://github.com/sst/opencode" target="_blank" rel="noreferrer">opencode</a> and <a href="https://github.com/badlogic/pi-mono" target="_blank" rel="noreferrer">pi</a>.</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>One runtime, two profiles: <code>general</code> keeps office/document behaviour; <code>coding</code> activates repository-aware prompting, stronger edit/search/shell tools, plan/todo/verification loops and recovery snapshots. Neither profile has a default turn, tool-call, token or wall-clock budget.</li><li>Match pi&#39;s coding loop and exceed it on verification, planning, background processes and benchmarkability. Reach roughly 80% of opencode&#39;s core harness without its Effect runtime, plugin market, multi-client architecture, codemode or provider matrix.</li><li>Every capability must be testable without a model. Model quality is evaluated separately with public benchmarks.</li></ul><h2 id="baseline-gaps" tabindex="-1">Baseline gaps <a class="header-anchor" href="#baseline-gaps" aria-label="Permalink to &quot;Baseline gaps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Before</th><th>Consequence</th></tr></thead><tbody><tr><td>Editing</td><td>Exact <code>oldText</code> match only</td><td>CRLF, indentation and Unicode quote drift fail; models retry blindly</td></tr><tr><td>Search</td><td>Hand-written walker with a narrow extension allowlist</td><td>Java, Go, Rust, generated and hidden files are missed</td></tr><tr><td>Shell</td><td>One <code>spawn</code> per call, timeout kills the tree</td><td>Servers, watchers, REPLs and long builds cannot be used</td></tr><tr><td>Context</td><td>8k character truncation; old tool output kept forever</td><td>Failures scroll out of context; compaction can split tool pairs</td></tr><tr><td>Completion</td><td>JSON deliverable check only</td><td>A coding task can &quot;finish&quot; without a test run</td></tr><tr><td>Loop</td><td>Serial tool calls; identical call skipped</td><td>Read-only batches are slow; retries are punished instead of no-progress loops</td></tr><tr><td>Prompt</td><td>Chinese office instructions plus benchmark-specific keyword rules</td><td>Wrong priors for repository work</td></tr><tr><td>Budget</td><td>24 turns / 64 tool calls in standard mode</td><td>Real coding tasks exceed the budget before verification</td></tr></tbody></table><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/server/src/native-executor.ts</span></span>
<span class="line"><span>  profile selection -&gt; coding prompt / budget / permissions</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>packages/agent-runtime/src/runtime.ts</span></span>
<span class="line"><span>  scheduler, tool batch partition, plan gate, per-tool timeout,</span></span>
<span class="line"><span>  no-progress detector, steering, checkpoints, post-edit hook</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>packages/agent-runtime/src/tools.ts</span></span>
<span class="line"><span>  read/write/edit/patch, shell sessions, todo, tests, diagnostics,</span></span>
<span class="line"><span>  plan, snapshots, memory, goals, shell_wait</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>packages/agent-runtime/src/harness/*</span></span>
<span class="line"><span>  profiles, agent profiles, environment, instructions, project profile,</span></span>
<span class="line"><span>  prompt sections, file state, edit matching, omission detection, output</span></span>
<span class="line"><span>  truncation, shell sessions, search, todo, verification, plan, snapshots,</span></span>
<span class="line"><span>  checkpoint state, post-compact restoration, command policy, memory, goal</span></span></code></pre></div><p><code>harness/*</code> modules are pure functions or small state objects. They do not import the server and can be unit tested directly.</p><h2 id="coding-profile" tabindex="-1">Coding profile <a class="header-anchor" href="#coding-profile" aria-label="Permalink to &quot;Coding profile&quot;">​</a></h2><p>Enabled by default; set <code>HEARTH_CODING_HARNESS=0</code> to force the general profile. A task selects <code>coding</code> when any of these is true:</p><ul><li><code>taskKind === &quot;workspace&quot;</code></li><li>the workspace contains <code>.git</code></li><li>the task text mentions code execution or GitHub operations</li></ul><p>The coding profile uses <code>CODING_RUN_BUDGET</code>, which is empty by default: there is no turn, tool-call, token or wall-clock limit unless a caller passes an explicit budget. It exposes the coding toolset dynamically. The prompt lists only tools that are actually callable for the current run. The set includes file ACI (<code>read_file</code>, <code>edit_file</code>, <code>apply_patch</code>), search, shell sessions (<code>shell</code>, <code>shell_output</code>, <code>shell_kill</code>, <code>shell_wait</code>), todo, tests, diagnostics, plan, snapshots (<code>rewind</code>, <code>rewind_turn</code>), typed subagents (<code>agent</code>, <code>agent_wait</code>, <code>agent_status</code>, <code>agent_kill</code>), repository memory and persisted goals.</p><h2 id="prompt-sections" tabindex="-1">Prompt sections <a class="header-anchor" href="#prompt-sections" aria-label="Permalink to &quot;Prompt sections&quot;">​</a></h2><p><code>codingPromptSections</code> returns stable, composable sections: <code>rules</code>, <code>tools</code>, <code>environment</code>, <code>memory</code>, <code>instructions</code>, <code>mode</code>, <code>skills</code> and <code>extra</code>. <code>codingSystemPrompt</code> joins the non-empty sections, so callers can inspect or reuse a section without rebuilding the whole prompt. The plan-mode section is always present and is backed by a runtime gate, not only by prompt text.</p><h2 id="editing-contract" tabindex="-1">Editing contract <a class="header-anchor" href="#editing-contract" aria-label="Permalink to &quot;Editing contract&quot;">​</a></h2><ol><li>The file must be read before it is edited, unless <code>write_file</code> is called with <code>overwrite=true</code>.</li><li>Content is normalized to LF and BOM is stripped for matching, then restored on write.</li><li>Matching tiers: exact, line trim, whitespace normalization, indentation, block anchor, similarity and Unicode normalization. Each tier must produce a unique match. Unicode matching decodes <code>\\uXXXX</code> and <code>\\xNN</code> escapes and folds curly quotes and zero-width characters while preserving original file offsets.</li><li>Omission placeholders (<code>...</code>, <code>// ... existing code ...</code>, <code>// 其余不变</code>) are rejected in both <code>edit_file</code> and <code>apply_patch</code> instead of being written as real code.</li><li>Multi-edit is atomic: one failed edit leaves the file untouched.</li><li>Every mutation snapshots the previous file under the task output directory and returns a snapshot id. Snapshots are grouped per turn; <code>rewind_turn</code> restores the previous completed turn or a named turn.</li><li>Repeated reads of an unchanged range return a short unchanged notice unless <code>force=true</code>. Binary files and missing paths return actionable errors, including similar filename suggestions.</li><li>A successful file-changing tool can trigger the optional <code>afterEdit</code> hook with the changed paths; hook failures are reported as notices and never abort the run.</li></ol><h2 id="verification-contract" tabindex="-1">Verification contract <a class="header-anchor" href="#verification-contract" aria-label="Permalink to &quot;Verification contract&quot;">​</a></h2><p><code>finish_task</code> for coding tasks is rejected when:</p><ul><li>a todo is not completed;</li><li>the repository has changes but the summary does not explain a read-only task;</li><li>conflict markers remain in changed files;</li><li>code changed and no test command ever ran;</li><li>the latest diagnostics contain errors.</li></ul><p><code>run_tests</code> and <code>diagnostics</code> use the detected project commands, record results in the progress ledger, and return structured failure metadata.</p><h2 id="loop-contract" tabindex="-1">Loop contract <a class="header-anchor" href="#loop-contract" aria-label="Permalink to &quot;Loop contract&quot;">​</a></h2><ul><li>Consecutive read-only tools may run in parallel up to <code>maxParallelTools</code>. Mixed batches are partitioned around sequential write tools: reads before and after a write keep their original order, and authorization and budget accounting still apply per call.</li><li>Plan mode is enforced at the tool boundary. Non-whitelisted tools are rejected before execution, and <code>shell</code> is limited to approved read-only commands.</li><li>Each tool has a timeout. A timed-out shell command is migrated to a background session instead of killing the process tree.</li><li>Repeated identical calls are allowed to a point; five identical call/result pairs stop the run with an explicit no-progress message.</li><li>Steering messages are drained at turn boundaries. Background subagent completion notices arrive through this channel.</li><li>Compaction keeps complete assistant/tool pairs, keeps the most recent tool outputs intact, prunes older output with head+tail, and injects a progress ledger plus project instructions.</li><li>After compaction, a <code>&lt;post_compact_context&gt;</code> block restores mode, recently read files with hashes and ranges, unfinished todos, the active plan, active skills and subagents.</li><li>Native checkpoints persist tool state and mode. Resume restores tool state only; historical usage stays deducted by the scheduler, so per-attempt counters start at zero and are not double-counted.</li></ul><h2 id="context-continuity" tabindex="-1">Context continuity <a class="header-anchor" href="#context-continuity" aria-label="Permalink to &quot;Context continuity&quot;">​</a></h2><p>The compaction summary is a nine-section structured report: primary request and intent, key technical concepts, files and code sections, errors and fixes, problem solving, all user messages, pending tasks, current work and suggested next steps. It must cite real paths, line numbers and commands; invented progress is rejected by review.</p><p>Read state is cleared after compaction so the summary is not treated as the original tool output, and <code>ranges</code> prevents duplicate reads only while the file content hash still matches.</p><h2 id="agent-orchestration" tabindex="-1">Agent orchestration <a class="header-anchor" href="#agent-orchestration" aria-label="Permalink to &quot;Agent orchestration&quot;">​</a></h2><p><code>agent</code> is the typed entry point. Profiles are:</p><table tabindex="0"><thead><tr><th>Profile</th><th>Mode</th><th>Isolation</th><th>Purpose</th></tr></thead><tbody><tr><td><code>explore</code></td><td>plan</td><td>read-only</td><td>Locate code and answer questions</td></tr><tr><td><code>plan</code></td><td>plan</td><td>read-only</td><td>Produce an implementation plan</td></tr><tr><td><code>review</code></td><td>plan</td><td>read-only</td><td>Inspect a diff for defects</td></tr><tr><td><code>general-purpose</code></td><td>build</td><td>worktree</td><td>Independent implementation</td></tr></tbody></table><p><code>delegate_task</code> remains a compatibility alias. Background agents return an id immediately and are managed by <code>agent_wait</code>, <code>agent_status</code> and <code>agent_kill</code>; parent cancellation propagates to children. Each child writes a JSONL transcript with prompt, summary, usage, messages, branch and commit. Completion notices are injected into the parent as steering messages rather than rewriting parent history.</p><h2 id="long-horizon-state" tabindex="-1">Long-horizon state <a class="header-anchor" href="#long-horizon-state" aria-label="Permalink to &quot;Long-horizon state&quot;">​</a></h2><ul><li><code>shell_wait</code> waits for a background process to exit, match output or time out instead of polling; the default wait is 60 seconds and the cap is 10 minutes. A timeout leaves the process running and returns its current output.</li><li>Repository memory lives in <code>.hearth/memory</code> with a <code>MEMORY.md</code> index; <code>memory_read</code>, <code>memory_write</code> and <code>memory_search</code> expose it to coding and read-only profiles. The index is bounded to 200 lines / 25 KB and is injected at prompt startup; topic bodies are loaded only on demand.</li><li>A long-running goal lives in <code>.hearth/goal.json</code>; <code>get_goal</code>, <code>create_goal</code> and <code>update_goal</code> persist title, objective, constraints, success criteria and plan path. Only one active goal is allowed. <code>finish_task</code> is rejected while a goal is active and turns are counted across runs, but <code>maxTurns</code> is advisory and never pauses execution.</li><li>Per-turn file history lives in <code>.hearth/file-history/turn-N/manifest.json</code> with before/after hashes, line deltas and created-file markers. <code>rewind_turn</code> restores the previous completed turn or a named turn, removes files created by that turn, reports partial failures, and keeps the most recent 100 turn manifests.</li><li>The older <code>rewind</code> remains available for a single snapshot, and per-turn snapshots are still persisted through checkpoints.</li></ul><h2 id="benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#benchmarks" aria-label="Permalink to &quot;Benchmarks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Benchmark</th><th>What it measures</th><th>Adapter</th></tr></thead><tbody><tr><td>Internal <code>hearth-coding</code> suite</td><td>Repository navigation, editing, tests, multi-file changes</td><td><code>scripts/bench/aci-bench.ts</code></td></tr><tr><td>Aider Polyglot</td><td>225 exercises, 6 languages, pass@2 and format errors</td><td><code>scripts/bench/run-suite.ts</code> + upstream dataset conversion</td></tr><tr><td>SWE-bench Verified</td><td>500 Python issues, easy/hard split</td><td><code>scripts/bench/run-suite.ts</code> + Docker patch adapter</td></tr><tr><td>Terminal-Bench 2.x</td><td>89 terminal tasks, 16 categories</td><td><code>scripts/bench/run-suite.ts</code> + Harbor container</td></tr></tbody></table><p>The public adapter is a generic JSONL suite runner: each task names a workspace, prompt and optional test command. The runner copies the workspace, invokes the same <code>run-agent</code> entry point as the server, executes the test command, captures <code>git diff --binary</code> and writes a report with <code>agentStatus</code>, <code>testExitCode</code>, <code>passed</code>, duration and patch. Container orchestration stays outside the harness so results remain comparable across benchmarks.</p><p>The first milestone is harness-only: all unit tests green and the internal suite improves over the recorded baseline for the same model. Public benchmark runs require Docker/Linux and are tracked separately.</p><h3 id="measured-aci-baseline" tabindex="-1">Measured ACI baseline <a class="header-anchor" href="#measured-aci-baseline" aria-label="Permalink to &quot;Measured ACI baseline&quot;">​</a></h3><p><code>scripts/bench/legacy-aci.ts</code> runs the same fixture tasks against the pre-change worktree (<code>c6fbf41</code>) and the new harness. Results from 2026-11-19:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Before</th><th style="text-align:right;">After</th></tr></thead><tbody><tr><td>Exact edit</td><td>pass</td><td style="text-align:right;">pass</td></tr><tr><td>CRLF + indentation edit</td><td>fail</td><td style="text-align:right;">pass</td></tr><tr><td>Multi-edit</td><td>fail</td><td style="text-align:right;">pass</td></tr><tr><td>Fuzzy patch context</td><td>fail</td><td style="text-align:right;">pass</td></tr><tr><td>Java search</td><td>fail</td><td style="text-align:right;">pass</td></tr><tr><td>Read-before-write guard</td><td>not present</td><td style="text-align:right;">pass</td></tr><tr><td>Background shell timeout</td><td>killed tree</td><td style="text-align:right;">migrated session</td></tr><tr><td><code>run_tests</code> / finish gate</td><td>missing</td><td style="text-align:right;">pass</td></tr><tr><td>Todo state</td><td>missing</td><td style="text-align:right;">pass</td></tr><tr><td>Rewind</td><td>missing</td><td style="text-align:right;">pass</td></tr><tr><td>Total</td><td>3/10</td><td style="text-align:right;">10/10</td></tr></tbody></table><p>Reports live in <code>eval/aci/pre-change.json</code> and <code>eval/aci/post-change.json</code>. These measure the harness, not model quality; model benchmarks still need a configured model and Docker.</p><h3 id="headless-runner" tabindex="-1">Headless runner <a class="header-anchor" href="#headless-runner" aria-label="Permalink to &quot;Headless runner&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent:run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/repo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Fix the failing test in src/cart.ts&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/hearth-run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --base-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.example.com/v1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --api-key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HEARTH_MODEL_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-model</span></span></code></pre></div><p>The runner uses the same coding prompt, tools, budget (unlimited by default) and finish gate as the server, so benchmark adapters can drive it without starting the desktop app.</p><h2 id="commit-policy" tabindex="-1">Commit policy <a class="header-anchor" href="#commit-policy" aria-label="Permalink to &quot;Commit policy&quot;">​</a></h2><ul><li>Work happens directly on <code>main</code>; no feature branch and no merge commits.</li><li>One logical change per commit.</li><li>Subject and body are English. Body uses <code>Why / What / Test</code>.</li><li>Generated assets, logs and personal files are never committed.</li></ul>`,45)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
